&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;About This Role&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;The&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;General Site Foreman&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;work&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;closely with members of the project management, infrastructure engineering, project&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;controls&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;and procurement departments from installation through start of production. Th&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;is role manages a team of laborers and carpenters to keep general project site organized and clean&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;. This role specifically includes scheduling&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;trade workers in&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;resolving&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;day-to-day&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;construction issues, performing day to day inspections to ensure compliance with plans and specifications while tracking project schedule and budget. This role work&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;directly with the Construction Manager&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;, General Site Superintendent,&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;&amp;nbsp;and Technical Project Manager&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62616166 BCX8&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&amp;nbsp;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Supervises all&amp;nbsp;construction site maintenance&amp;nbsp;for the&amp;nbsp;project site and liaises between engineering, estimating, and workforce to ensure project compliance with contract drawings and specifications.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Directly responsible&amp;nbsp;for supervising all&amp;nbsp;site laborers and carpenters for site coordination.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;General upkeep of site restrooms, disposal bins, safety system install/maintenance,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Supervises site&amp;nbsp;logistics&amp;nbsp;of the project site for deliveries, site activities, adjacent project coordination, and field scopes&amp;nbsp;with project team and trade subcontractors.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Plans work methods, materials, equipment&amp;nbsp;needs&amp;nbsp;and work schedule for assigned project work. Reviews daily work schedule with direct reports and updates weekly schedule from project feedback.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Reviews and understands the project specifications to support job set up activities. Works with work crews, field engineers, design engineers, local utility companies, and local statutory agencies to safely manage piping scopes on job site.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Forecasts the work schedule to&amp;nbsp;identify&amp;nbsp;possible issues&amp;nbsp;and provides technical or scheduling recommendations to mitigate production issues.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Provides technical input to&amp;nbsp;identify&amp;nbsp;and resolve project risks including construction methods, work plan and material requirements,&amp;nbsp;safety&amp;nbsp;and schedule activities. Documents daily activities and meeting notes using Company approved document methods.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Performs&amp;nbsp;additional&amp;nbsp;assignments per management’s direction.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Presents production work plan during&amp;nbsp;initial&amp;nbsp;project meeting to ensure all project crews and leaders are in alignment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Coordinates with internal equipment team and external vendors to ensure that project work is equipped with&amp;nbsp;appropriate equipment&amp;nbsp;and material quantities to complete production within assigned budget and schedule.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Coordinates with internal and external departments to ensure all mandated inspections are completed within requested&amp;nbsp;timeframes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Supports and promotes strict adherence to safety and process controls&amp;nbsp;regarding&amp;nbsp;operating equipment, worksite&amp;nbsp;safety&amp;nbsp;and documentation requirements. Responsibility includes recommending training needs&amp;nbsp;identified&amp;nbsp;on jobsite.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Supervises sub-contractor production and workforce&amp;nbsp;regarding&amp;nbsp;assigned project work. Recommends work schedule or work method adjustments&amp;nbsp;regarding&amp;nbsp;sub-contractor activities, as needed.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Coordinates&amp;nbsp;project&amp;nbsp;close out activities in line with Company standards and AHJ checklist requirements.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Maintains knowledge of Company values and strategic plan.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
