&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deep, hands-on&amp;nbsp;expertise&amp;nbsp;with the Critical Path Method (CPM), building and&amp;nbsp;maintaining&amp;nbsp;fully logic-driven schedules from scratch (WBS setup, calendars, activity coding, resource&amp;nbsp;loading&amp;nbsp;and leveling) for large, multi-billion-dollar facilities, not just tracking milestones or bar charts.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;12+ years of planning and scheduling experience on large-scale EPC or industrial capital projects.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor&#39;s degree in engineering, construction management, or a related field (or equivalent experience).&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Advanced&amp;nbsp;proficiency&amp;nbsp;in Oracle Primavera P6 and Microsoft Project.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
