&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Extend and customize platforms directly through their native tools, such as server-side scripting, query languages, workflow automation, and custom objects, when out-of-the-box configuration is not enough.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:80,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
